WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Follow-up duration for primary endpoint(s) in months | Overall" AS source_value FROM clinical_trials
WHERE "Cancer type" = 'Urothelial'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_followup_bucket(source_value) AS "followup_bucket"
FROM base;
